// ============================================================
// NODE: Normalize & Extract Email Fields
// PURPOSE: Pull clean fields from the raw Gmail payload so
//          every downstream node works with consistent data.
// ============================================================

const item = $input.item.json;

// --- Extract sender name and email separately ---
const fromRaw = item.from || '';
let senderEmail = '';
let senderName = '';

const emailMatch = fromRaw.match(/<([^>]+)>/);
if (emailMatch) {
  senderEmail = emailMatch[1].trim().toLowerCase();
  senderName = fromRaw.split('<')[0].trim().replace(/"/g, '');
} else {
  // Plain email with no display name
  senderEmail = fromRaw.trim().toLowerCase();
  senderName = fromRaw.split('@')[0].trim();
}

// --- Extract first name from sender name ---
const firstName = senderName.split(' ')[0] || 'there';

// --- Get the best body text available ---
// Gmail returns both plain text and HTML — prefer plain text
const bodyText = item.text || item.snippet || '';
const bodyClean = bodyText
  .replace(/\r\n/g, '\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim()
  .substring(0, 3000); // Cap at 3000 chars for AI token efficiency

// --- Build full text for safety/classification analysis ---
const fullText = `${item.subject || ''} ${bodyClean}`.toLowerCase();

return {
  json: {
    // Core identifiers
    messageId:    item.id || '',
    threadId:     item.threadId || '',
    // Sender info
    senderEmail,
    senderName,
    firstName,
    // Email content
    subject:      item.subject || '(No Subject)',
    body:         bodyClean,
    fullTextLower: fullText,
    // Metadata
    receivedAt:   item.date || new Date().toISOString(),
    // Pass through raw for reference
    _raw:         item
  }
};

// ============================================================
// NODE: Safety Filter
// PURPOSE: Check for ANY language that should NEVER be
//          auto-replied to. This is the most important
//          safety gate in the entire workflow.
// RULE:    If in doubt → flag it. Never auto-reply to
//          anything sensitive.
// ============================================================

const text = $input.item.json.fullTextLower || '';

// --- CATEGORY 1: Legal & Complaint language ---
const legalPatterns = [
  'complaint', 'complain', 'solicitor', 'solicitors',
  'legal action', 'legal proceedings', 'lawsuit', 'sue you',
  'taking you to court', 'court action', 'ombudsman',
  'data breach', 'gdpr breach', 'ico', 'regulator',
  'negligence', 'malpractice', 'report you', 'trading standards'
];

// --- CATEGORY 2: Safeguarding & Risk ---
const safeguardingPatterns = [
  'safeguarding', 'safeguard', 'at risk', 'risk of harm',
  'child at risk', 'abuse', 'neglect', 'exploitation',
  'domestic violence', 'domestic abuse', 'threatened',
  'threatening', 'violence', 'police', 'social services'
];

// --- CATEGORY 3: Mental health crisis & urgent risk ---
const crisisPatterns = [
  'suicid', 'self harm', 'self-harm', 'selfharm',
  'overdose', 'want to die', 'end my life', 'end it all',
  'hurt myself', 'hurting myself', 'crisis', 'emergency',
  'urgent help', 'in danger', 'not safe'
];

// --- Check all categories ---
const matchedLegal       = legalPatterns.filter(p => text.includes(p));
const matchedSafeguarding = safeguardingPatterns.filter(p => text.includes(p));
const matchedCrisis      = crisisPatterns.filter(p => text.includes(p));

const isFlagged = matchedLegal.length > 0 || matchedSafeguarding.length > 0 || matchedCrisis.length > 0;

let flagReason = '';
let flagCategory = '';

if (matchedCrisis.length > 0) {
  flagCategory = 'CRISIS_RISK';
  flagReason = `Crisis/risk language detected: ${matchedCrisis.join(', ')}`;
} else if (matchedSafeguarding.length > 0) {
  flagCategory = 'SAFEGUARDING';
  flagReason = `Safeguarding language detected: ${matchedSafeguarding.join(', ')}`;
} else if (matchedLegal.length > 0) {
  flagCategory = 'LEGAL_COMPLAINT';
  flagReason = `Legal/complaint language detected: ${matchedLegal.join(', ')}`;
}

return {
  json: {
    ...$input.item.json,
    safety: {
      isFlagged,
      flagCategory,
      flagReason
    }
  }
};

// ============================================================
// NODE: Log Flagged Email to Google Sheets
// PURPOSE: Ensure every flagged email is tracked even though
//          no auto-reply was sent.
// ============================================================
// This node just passes data through — the actual Sheets write
// happens in the node after this one. We keep it here to
// allow adding extra logic (e.g. Slack alert) between flag
// and logging without breaking the flow.

return {
  json: {
    ...$input.item.json,
    logStatus: 'FLAGGED_NO_REPLY',
    autoReplied: false
  }
};

// ============================================================
// NODE: Parse & Validate AI Response
// PURPOSE: Safely parse the AI JSON. Handle every possible
//          failure mode so the workflow NEVER crashes here.
// RULE:    If anything goes wrong → manual_review.
// ============================================================

const upstream = $input.item.json;
let aiText = '';

// Handle different response shapes from OpenAI node
try {
  aiText = upstream.text
    || upstream.message?.content
    || upstream.choices?.[0]?.message?.content
    || upstream.content?.[0]?.text
    || '';
} catch(e) {
  aiText = '';
}

let classification = {};

try {
  // Strip any accidental markdown fences
  const cleaned = aiText
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();

  classification = JSON.parse(cleaned);

  // Validate required fields exist
  const required = ['category', 'confidence'];
  for (const field of required) {
    if (classification[field] === undefined) {
      throw new Error(`Missing required field: ${field}`);
    }
  }

} catch (e) {
  // Parsing failed — force manual review, log the error
  classification = {
    category: 'manual_review',
    confidence: 0,
    reasoning: `AI response parse failed: ${e.message}. Raw response: ${aiText.substring(0, 200)}`,
    firstName: '',
    isChild: false,
    gpName: '',
    location: '',
    mentionsPrice: false,
    mentionsWaitingTime: false,
    appointmentType: 'Unknown'
  };
}

// --- Confidence gate ---
// Even if AI returned a category, if confidence is too low → manual review
if (classification.confidence < 0.75 && classification.category !== 'manual_review') {
  classification.originalCategory = classification.category;
  classification.category = 'manual_review';
  classification.reasoning = `Low confidence (${classification.confidence.toFixed(2)}). Original guess was: ${classification.originalCategory}. ${classification.reasoning}`;
}

// --- Use AI-extracted firstName if better than what we parsed from sender ---
// Sender name parsing gets 'John Smith' → 'John'
// AI may extract 'my daughter Emily' → 'Emily' (the actual patient)
const bestFirstName = (
  (classification.firstName && classification.firstName.trim() !== '')
    ? classification.firstName
    : upstream.firstName
) || 'there';

return {
  json: {
    // Pass through all upstream fields
    ...upstream,
    // Override firstName with best available
    firstName: bestFirstName,
    // Attach classification
    ai: classification,
    category: classification.category,
    confidence: classification.confidence,
    // Convenience booleans used by template nodes
    isChild: classification.isChild || false,
    mentionsPrice: classification.mentionsPrice || false,
    mentionsWaitingTime: classification.mentionsWaitingTime || false,
    gpName: classification.gpName || '',
    location: classification.location || '',
    appointmentType: classification.appointmentType || ''
  }
};

// ============================================================
// NODE: Build Template — Adult ADHD Assessment
// ============================================================
// INSTRUCTIONS: Replace the TEMPLATE_BODY section below
// with your actual adult ADHD assessment template text.
// Keep the {{ firstName }} and conditional blocks — they
// auto-insert personalisation at send time.
// ============================================================

const d = $input.item.json;
const firstName = d.firstName || 'there';

let body = `Dear ${firstName},

Thank you so much for getting in touch with us — we really appreciate you reaching out.

// ============================================================
// ▼▼▼ PASTE YOUR ADULT ADHD ASSESSMENT TEMPLATE BELOW ▼▼▼
// ============================================================

We would be delighted to support you through our adult ADHD assessment pathway. Our assessments are carried out by experienced specialist consultants who provide a thorough, compassionate evaluation tailored to you.

The process typically involves:
• An initial consultation to understand your background and concerns
• A comprehensive diagnostic assessment (usually 2–3 hours)
• A detailed written report with our findings and recommendations
• A follow-up appointment to discuss next steps and, if appropriate, treatment options

// ============================================================
// ▲▲▲ PASTE YOUR TEMPLATE ABOVE THIS LINE ▲▲▲
// ============================================================
`;

// --- Conditional: Waiting time ---
if (d.mentionsWaitingTime) {
  body += `\nRegarding your question about waiting times: we are currently seeing new adult assessment patients within approximately [X weeks] of receiving a completed referral. We will confirm your exact appointment date as soon as your information is received.\n`;
}

// --- Conditional: Pricing ---
if (d.mentionsPrice) {
  body += `\nRegarding fees: our adult ADHD assessment is priced at [£XXX]. This covers the full assessment, written report, and follow-up consultation. We will provide a complete breakdown when confirming your appointment.\n`;
}

// --- Conditional: Location ---
if (d.location) {
  body += `\nWe note you mentioned ${d.location} — we can confirm we have [clinic/remote] options available that would be convenient for you.\n`;
}

body += `\nTo take the next step, please reply to this email or call us on [PHONE NUMBER] and one of our friendly admin team will be happy to help.\n\nWarm regards,\n[Admin Name]\nAdmin Team\n[Clinic Name]\n[Phone Number] | [Website]`;

return {
  json: {
    ...d,
    emailSubject: `Re: ${d.subject}`,
    emailBody: body,
    categoryLabel: 'Adult ADHD Assessment',
    ccEmail: 'REPLACE_ADULT_ADHD_CONSULTANT@yourclinic.co.uk'
  }
};

// ============================================================
// NODE: Build Template — Child ADHD Assessment
// ============================================================
// NOTE: Tone is warmer and directed at the parent/guardian.
// The firstName here is the CHILD's name if AI detected it,
// or the sender's name if not.
// ============================================================

const d = $input.item.json;
const firstName = d.firstName || 'there';

let body = `Dear ${firstName},

Thank you for reaching out to us. We understand how important it is to get the right support for your child, and we want you to know you've come to the right place.

// ============================================================
// ▼▼▼ PASTE YOUR CHILD ADHD ASSESSMENT TEMPLATE BELOW ▼▼▼
// ============================================================

Our child ADHD assessment is conducted by specialist paediatric consultants who are experienced in working with children and young people of all ages. We create a relaxed, friendly environment to make the process as comfortable as possible for both your child and your family.

The assessment typically includes:
• A detailed parent/guardian consultation
• A direct assessment session with your child (age-appropriate)
• Liaison with school if appropriate and consented
• A comprehensive written report
• A follow-up appointment to discuss findings and next steps

// ============================================================
// ▲▲▲ PASTE YOUR TEMPLATE ABOVE THIS LINE ▲▲▲
// ============================================================
`;

if (d.mentionsWaitingTime) {
  body += `\nRegarding waiting times: we are currently booking child assessments within approximately [X weeks]. We will be in touch shortly to arrange a time that suits your family.\n`;
}

if (d.mentionsPrice) {
  body += `\nRegarding our fees: the child ADHD assessment is [£XXX]. Full details will be provided when we confirm the appointment.\n`;
}

body += `\nIf you have any questions at all — please don't hesitate to get in touch. We're always happy to speak with you.\n\nWarm regards,\n[Admin Name]\nAdmin Team\n[Clinic Name]\n[Phone Number] | [Website]`;

return {
  json: {
    ...d,
    emailSubject: `Re: ${d.subject}`,
    emailBody: body,
    categoryLabel: 'Child ADHD Assessment',
    ccEmail: 'REPLACE_CHILD_ADHD_CONSULTANT@yourclinic.co.uk'
  }
};

// ============================================================
// NODE: Build Template — Follow-Up Enquiry
// ============================================================

const d = $input.item.json;
const firstName = d.firstName || 'there';

let body = `Dear ${firstName},

Thank you for getting in touch with us.

// ============================================================
// ▼▼▼ PASTE YOUR FOLLOW-UP TEMPLATE BELOW ▼▼▼
// ============================================================

We have received your follow-up enquiry and a member of our team will review this and get back to you as soon as possible.

If your query is time-sensitive, please don't hesitate to call us directly on [PHONE NUMBER] during our office hours ([HOURS]).

// ============================================================
// ▲▲▲ END OF TEMPLATE ▲▲▲
// ============================================================

Kind regards,\n[Admin Name]\nAdmin Team\n[Clinic Name]\n[Phone Number] | [Website]`;

return {
  json: {
    ...d,
    emailSubject: `Re: ${d.subject}`,
    emailBody: body,
    categoryLabel: 'Follow-Up Enquiry',
    ccEmail: 'REPLACE_ADMIN@yourclinic.co.uk'
  }
};

// ============================================================
// NODE: Build Template — Medication Query
// ============================================================
// IMPORTANT: Never provide clinical advice in auto-replies.
// This template acknowledges the query and directs to the
// prescribing consultant. Safety first.
// ============================================================

const d = $input.item.json;
const firstName = d.firstName || 'there';

let body = `Dear ${firstName},

Thank you for contacting us regarding your medication.

// ============================================================
// ▼▼▼ PASTE YOUR MEDICATION QUERY TEMPLATE BELOW ▼▼▼
// ============================================================

We have received your query and will ensure it is passed on to the appropriate member of your care team.

Please note that for specific clinical advice regarding your medication — including dosage, side effects, or any changes to your prescription — you will need to speak directly with your prescribing consultant. Our admin team are not able to provide clinical guidance.

We will aim to respond with further information within [X working days]. If this is urgent, please call us on [PHONE NUMBER].

// ============================================================
// ▲▲▲ END OF TEMPLATE ▲▲▲
// ============================================================

Kind regards,\n[Admin Name]\nAdmin Team\n[Clinic Name]\n[Phone Number] | [Website]`;

return {
  json: {
    ...d,
    emailSubject: `Re: ${d.subject}`,
    emailBody: body,
    categoryLabel: 'Medication Query',
    ccEmail: 'REPLACE_PRESCRIPTIONS@yourclinic.co.uk'
  }
};

// ============================================================
// NODE: Build Template — GP / Shared Care
// ============================================================
// Tone is professional and clinical — this email may be going
// to a GP, practice manager, or NHS professional.
// If AI detected the GP's name it is inserted automatically.
// ============================================================

const d = $input.item.json;
const recipientName = d.gpName ? `Dr ${d.gpName}` : (d.firstName !== 'there' ? d.firstName : 'Doctor');

let body = `Dear ${recipientName},

Thank you for your enquiry regarding shared care arrangements.

// ============================================================
// ▼▼▼ PASTE YOUR GP / SHARED CARE TEMPLATE BELOW ▼▼▼
// ============================================================

We welcome referrals and shared care arrangements with GP practices and are committed to working collaboratively to support your patients.

To proceed, we would ask that you provide the following information:
• Patient name and date of birth
• Reason for referral / current concerns
• Any relevant history or previous assessments
• Your preferred contact method for clinical correspondence

A member of our clinical team will review your enquiry and respond within [X working days].

// ============================================================
// ▲▲▲ END OF TEMPLATE ▲▲▲
// ============================================================

We look forward to working with you to support your patient's care.\n\nKind regards,\n[Admin Name]\nAdmin Team\n[Clinic Name]\n[Phone Number] | [Website]`;

return {
  json: {
    ...d,
    emailSubject: `Re: ${d.subject}`,
    emailBody: body,
    categoryLabel: 'GP / Shared Care',
    ccEmail: 'REPLACE_GP_LIAISON@yourclinic.co.uk'
  }
};

// ============================================================
// NODE: Build Template — General Enquiry
// ============================================================

const d = $input.item.json;
const firstName = d.firstName || 'there';

let body = `Dear ${firstName},

Thank you for getting in touch with us.

// ============================================================
// ▼▼▼ PASTE YOUR GENERAL ENQUIRY TEMPLATE BELOW ▼▼▼
// ============================================================

We have received your enquiry and a member of our admin team will be in touch shortly with a full response.

In the meantime, if you have any urgent questions, you're welcome to call us on [PHONE NUMBER] during office hours ([HOURS]).

// ============================================================
// ▲▲▲ END OF TEMPLATE ▲▲▲
// ============================================================

Kind regards,\n[Admin Name]\nAdmin Team\n[Clinic Name]\n[Phone Number] | [Website]`;

return {
  json: {
    ...d,
    emailSubject: `Re: ${d.subject}`,
    emailBody: body,
    categoryLabel: 'General Enquiry',
    ccEmail: 'REPLACE_ADMIN@yourclinic.co.uk'
  }
};

// ============================================================
// NODE: Prepare Log Row
// PURPOSE: Build a clean, consistent data object for logging
//          to Google Sheets and creating the Drive folder.
//          Runs after successful send.
// ============================================================

const d = $input.item.json;

return {
  json: {
    ...d,
    logStatus: 'AUTO_REPLIED',
    autoReplied: true,
    logTimestamp: new Date().toISOString(),
    logDate: new Date().toLocaleDateString('en-GB'),
    logTime: new Date().toLocaleTimeString('en-GB'),
    folderName: `${new Date().toISOString().split('T')[0]} — ${d.senderName} — ${d.categoryLabel || d.category}`
  }
};
